{
  "name": "danger-plugin-yarn",
  "description": "Provides dependency information on dependency changes in a PR",
  "author": {
    "name": "Orta Therox",
    "email": "orta.therox@gmail.com"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/orta/danger-plugin-yarn.git"
  },
  "bugs": {
    "url": "https://github.com/orta/danger-plugin-yarn/issues"
  },
  "homepage": "https://github.com/orta/danger-plugin-yarn#readme",
  "keywords": [
    "danger",
    "danger-plugin",
    "yarn"
  ],
  "version": "1.7.1",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "precommit": "lint-staged",
    "commit": "git-cz",
    "commitmsg": "validate-commit-msg",
    "build": "tsc",
    "test": "jest",
    "predocs": "rm -rf docs/",
    "docs": "esdoc -c .esdoc.json",
    "prepublishOnly": "npm run build",
    "semantic-release": "semantic-release pre && npm publish && semantic-release post",
    "prettier": "prettier",
    "prettier-write": "npm run prettier -- --parser typescript --no-semi --trailing-comma es5 --write --print-width 120",
    "prettier-project": "npm run prettier-write -- 'src/**/*.{ts,tsx}'"
  },
  "license": "MIT",
  "engines": {
    "node": ">=4.0.0"
  },
  "dependencies": {
    "date-fns": "^1.28.5",
    "lodash.flatten": "^4.4.0",
    "lodash.includes": "^4.3.0",
    "node-fetch": "^2.6.0",
    "semver": "^5.4.1"
  },
  "devDependencies": {
    "@types/jest": "^19.2.4",
    "@types/node": "^10.0.29",
    "commitizen": "^2.9.6",
    "cz-conventional-changelog": "^2.0.0",
    "danger": "*",
    "esdoc": "^0.5.2",
    "husky": "^0.13.3",
    "jest": "^20.0.1",
    "lint-staged": "^3.4.1",
    "prettier": "^1.3.1",
    "semantic-release": "^6.3.6",
    "ts-jest": "^20.0.0",
    "tslint": "^5.4.3",
    "typescript": "^4.6",
    "validate-commit-msg": "^2.12.1"
  },
  "config": {
    "commitizen": {
      "path": "cz-conventional-changelog"
    }
  },
  "lint-staged": {
    "*.@(ts|tsx)": [
      "tslint --fix",
      "npm run prettier-write --",
      "git add"
    ]
  },
  "jest": {
    "moduleFileExtensions": [
      "ts",
      "tsx",
      "js"
    ],
    "transform": {
      ".(ts|tsx)": "<rootDir>/node_modules/ts-jest/preprocessor.js"
    },
    "testRegex": "(.test)\\.(ts|tsx)$",
    "testPathIgnorePatterns": [
      "\\.snap$",
      "<rootDir>/node_modules/"
    ]
  }
}

{
  "name": "vscode-twoslash-queries",
  "displayName": "Twoslash Query Comments",
  "description": "Adds support for twoslash query comments (// ^?) in TypeScript and JavaScript projects",
  "publisher": "Orta",
  "version": "1.6.0",
  "engines": {
    "vscode": "^1.67.0"
  },
  "icon": "icon.png",
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onLanguage:javascript",
    "onLanguage:javascriptreact",
    "onLanguage:typescript",
    "onLanguage:typescriptreact",
    "onLanguage:jsx-tags"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/orta/vscode-twoslash-queries"
  },
  "main": "./out/extension.js",
  "browser": "./out/extension.js",
  "scripts": {
    "vscode:prepublish": "yarn run compile",
    "compile": "tsc -p ./",
    "watch": "tsc -watch -p ./",
    "pretest": "yarn run compile && yarn run lint",
    "lint": "eslint src --ext ts",
    "test": "node ./out/test/runTest.js"
  },
  "devDependencies": {
    "@types/vscode": "^1.67.0",
    "@types/glob": "^7.2.0",
    "@types/mocha": "^9.1.0",
    "@types/node": "14.x",
    "@typescript-eslint/eslint-plugin": "^5.49.0",
    "@typescript-eslint/parser": "^5.49.0",
    "eslint": "^8.9.0",
    "glob": "^7.2.0",
    "mocha": "^9.2.1",
    "typescript": "^4.9.0",
    "@vscode/test-electron": "^2.1.2"
  },
  "contributes": {
    "configuration": {
      "title": "Twoslash Query Comments",
      "properties": {
        "orta.vscode-twoslash-queries.maxLength": {
          "type": "number",
          "default": 120,
          "description": "Optionally set a maximum length for the hints to display."
        },
        "orta.vscode-twoslash-queries.enableStrictEnd": {
          "type": "boolean",
          "default": false,
          "description": "If enabled, type hints are shown only for queries that strictly end with '^?'."
        }
      }
    },
    "commands": [
      {
        "command": "orta.vscode-twoslash-queries.insert-twoslash-query",
        "title": "TwoSlash Query: Insert Below"
      },
      {
        "command": "orta.vscode-twoslash-queries.insert-inline-query",
        "title": "Inline TwoSlash Query: Insert EOL"
      }
    ],
    "menus": {
      "commandPalette": [
        {
          "command": "orta.vscode-twoslash-queries.insert-twoslash-query",
          "when": "editorLangId == typescript || editorLangId == typescriptreact || editorLangId == javascript || editorLangId == javascriptreact"
        },
        {
          "command": "orta.vscode-twoslash-queries.insert-inline-query",
          "when": "editorLangId == typescript || editorLangId == typescriptreact || editorLangId == javascript || editorLangId == javascriptreact"
        }
      ]
    },
    "keybindings": [
      {
        "command": "orta.vscode-twoslash-queries.insert-twoslash-query",
        "when": "editorTextFocus",
        "key": "ctrl+k 6",
        "mac": "cmd+k 6"
      },
      {
        "command": "orta.vscode-twoslash-queries.insert-inline-query",
        "when": "editorTextFocus",
        "key": "ctrl+k 7",
        "mac": "cmd+k 7"
      }
    ]
  }
}

