  "version": "0.0.0",
  "private": true,
  "description": "Serves the built demo and draws the Open Graph image for a shared plant",
  "type": "module",
  "scripts": {
    "start": "tsx src/index.ts",
    "dev": "tsx watch src/index.ts",
