import { defineConfig } from 'vite'

/**
 * The demo playground. `demo/main.ts` imports straight from `src/`, so editing a leaf,
 * pot or stem module hot-reloads the drawing without a build step — which is the only
 * feedback loop that matters when the output is a picture.
 */
export default defineConfig({
  // Absolute, because routes are real paths now: a relative asset URL on `/plant/monstera`
  // would resolve against `/plant/`, and the page would come up blank.
  base: '/',
  // The default `appType: 'spa'` gives every unknown path index.html, which is what makes
  // reloading `/plant/monstera` work in dev. `server/` does the same thing in production.
  server: { port: 5173 },
  build: { outDir: 'demo-dist', emptyOutDir: true },
})

