module.exports = (config, { mode }) => {
  if (mode === 'development') {
    relayCompiler = spawn('yarn', ['relay', '--watch'], { shell: true })

    relayCompiler.stdout.on('data', (data) => {
      console.log(`Relay: ${data}`.trim())
    })

    relayCompiler.stderr.on('data', (data) => {
      console.log(`Relay ERR: ${data}`.trim())
    })
  }

